/**
 * Merges chrome.webRequest's HttpHeader[] into a plain header map. Multiple
 * headers with the same name (legal for Server-Timing, Set-Cookie, etc.)
 * are joined with ", " to match how the Fetch API's Headers object behaves,
 * so the parsing layer sees the same shape either way.
 */
function toHeaderMap(headers: chrome.webRequest.HttpHeader[] | undefined): Record<string, string> {
  const map: Record<string, string> = {};
  for (const h of headers ?? []) {
    if (h.value === undefined) continue;
    const name = h.name.toLowerCase();
    map[name] = name in map ? `${map[name]}, ${h.value}` : h.value;
  }
  return map;
}

